            "set sv_maxclients ": "set sv_maxclients \"{{server.environment.MAX_PLAYERS}}\"",
            "set g_password ": "set g_password \"{{server.environment.SERVER_PASSWORD}}\"",
            "set rconpassword ": "set rconpassword \"{{server.environment.RCON_PASSWORD}}\"",
            "set server_motd0 ": "set server_motd0 \"{{server.environment.MOTD}}\"",
            "set com_watchdog_cmd ": "set com_watchdog_cmd \"exec {{server.environment.MAP_CYCLE}}.cfg\""
        }
    }
}
